"use strict";
const form=document.querySelector('#account-form'),status=document.querySelector('#account-status');
document.querySelector('.password-toggle').addEventListener('click',e=>{const button=e.currentTarget,input=form.elements.password,visible=input.type==='password';input.type=visible?'text':'password';button.setAttribute('aria-pressed',String(visible));button.setAttribute('aria-label',visible?'Nascondi password':'Mostra password');button.querySelector('.eye-slash').style.display=visible?'none':'';});
form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;status.textContent='';status.classList.remove('login-success');const data=Object.fromEntries(new FormData(form));for(const k of ['terms','privacy','marketing','remember'])data[k]=data[k]==='on';try{if(document.body.dataset.mode==='registrati'&&data.password!==data.password_confirm)throw Error('Le password non coincidono.');const r=await fetch('/api/'+(document.body.dataset.mode==='registrati'?'register':'login'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),d=await r.json();if(!r.ok)throw Error(d.error);if(document.body.dataset.mode==='login'){status.classList.add('login-success');const check=document.createElement('span');check.className='login-check';check.setAttribute('aria-hidden','true');check.textContent='✓';status.replaceChildren(check,document.createTextNode('Accesso riuscito'));button.textContent='Accesso riuscito';await new Promise(resolve=>setTimeout(resolve,1200))}location.assign(d.redirect||'/#contatti')}catch(err){status.textContent=err.message||'Accesso non disponibile.';button.disabled=false}});
